console.log(findDuplicates(['a', 'b', 'c', 'b', 'a'])); // ['b', 'a']
console.log(findDuplicates([1, '1', 1, '1'])); // [1, '1']
console.log(findDuplicates([])); // []
console.log(findDuplicates([1, 2, 3])); // []
console.log(findDuplicates([true, false, true, 1, true])); // [true]
```

The function handles all these cases correctly.

Final implementation:

```js
function findDuplicates(arr) {
    const seen = new Set();
    const duplicates = [];
    const addedToDuplicates = new Set();

    for (const item of arr) {
        if (seen.has(item)) {
            if (!addedToDuplicates.has(item)) {
                duplicates.push(item);
                addedToDuplicates.add(item);
            }
        } else {
            seen.add(item);
        }
    }

    return duplicates;
}
```

